using System;using System.Linq;using System.Text.Json;using UnityEngine;using TMPro;using KO.HollowKnight8;
internal static class Test {
 static int checks;
 static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
 static Local8Runtime Fresh(int count=1){CoopSetupHint.Uninstall();RescueHint.Reset();JoinHint.Reset();Local8Mod.Save=new();GameObject.All.Clear();Resources.All.Clear();Resources.All.Add(new TMP_FontAsset{name="Trajan Pro"});Time.unscaledTime+=100;Time.unscaledDeltaTime=.1f;GameManager.instance=new();var canvas=new GameObject("HUD",typeof(RectTransform));UIManager.instance=new(){UICanvas=(RectTransform)canvas.transform};var r=new Local8Runtime();r.Session.Players=Enumerable.Range(0,count).Select(i=>new PlayerSlot{Index=i}).ToList();Plugin.Self=r;Charms.NativeMenuOpen=ScriptedParty.Active=CoopEnding.Active=StagMenuRouting.HasOwner=PvpMatch.BlocksInput=TransitionVote.Exit=false;PickupCard.Owner=ShopMenuRouting.Buyer=InteractionRouter.ActivePlayer=null;MenuInput.Key=KeyCode.F8;CoopSetupHint.Install();return r;}
 static TextMeshProUGUI Label(string name)=>GameObject.All.Where(g=>g&&g.name==name).Select(g=>g.GetComponent<TextMeshProUGUI>()).FirstOrDefault(t=>t);
 static void Tick(Local8Runtime r,float seconds=.1f){Time.unscaledTime+=seconds;Time.unscaledDeltaTime=seconds;RescueHint.Tick(r.Session);CoopSetupHint.Tick(r);JoinHint.Tick(r);}
 static void Main(){
  var r=Fresh();for(int i=0;i<30;i++)Tick(r);Check(!CoopSetupHint.Pending&&Label("Local8 Co-op Setup Hint")==null&&Local8Mod.Save.CoopSetupHintState==0,"existing save received a new-game notice");
  CoopSetupHint.Install();Check(Modding.ModHooks.Subscribers==1,"duplicate new-game hook");Modding.ModHooks.NewGame();Modding.ModHooks.NewGame();Check(Local8Mod.Save.CoopSetupHintState==1,"native new-game event did not arm exactly one notice");
  Tick(r);var label=Label("Local8 Co-op Setup Hint");Check(label&&label.enabled&&label.text=="F8 TO CONFIGURE CO-OP MODE","solo new-game notice missing");
  Check(label.font.name=="Trajan Pro"&&label.fontSize==25&&label.alignment==TextAlignmentOptions.Center&&!label.raycastTarget&&!label.enableWordWrapping,"native rescue-hint typography changed");
  var rect=label.GetComponent<RectTransform>();Check(rect.anchorMin.x==.05f&&rect.anchorMin.y==.12f&&rect.anchorMax.x==.95f&&rect.anchorMax.y==.18f&&label.color.r==.95f&&label.color.g==.93f&&label.color.b==.86f,"native rescue-hint placement/color changed");
  Check(Label("Local8 Join Hint")==null,"initial notices overlap");Check(Local8Mod.Save.CoopSetupHintState==2,"notice not marked on the actual save");
  var data=JsonSerializer.Serialize(Local8Mod.Save,new JsonSerializerOptions{IncludeFields=true});var loaded=JsonSerializer.Deserialize<Local8SaveData>(data,new JsonSerializerOptions{IncludeFields=true});Check(loaded.CoopSetupHintState==2,"shown flag not preserved by save serialization");
  foreach(string language in new[]{"ES","EN","FR","DE","IT","PT","RU","ZH","JA","KO"}){Language.Language.Code=language;MenuInput.Key=KeyCode.F7;Tick(r);Check(label.text==string.Format(RoleText.Get("ui.coop_setup_hint"),"F7")&&!label.text.Contains("{0}")&&!label.text.Contains("ui."),"language or configured key not updated: "+language);}
  Language.Language.Code="EN";for(int i=0;i<150;i++)Tick(r);Check(!CoopSetupHint.Pending&&!label,"notice did not fade/finish");
  Modding.ModHooks.NewGame();Tick(r);Check(!CoopSetupHint.Pending,"duplicate native callback repeated a displayed notice");CoopSetupHint.Reset();Local8Mod.Save=loaded;for(int i=0;i<20;i++)Tick(r);Check(Label("Local8 Co-op Setup Hint")==null,"loading the same save repeated the notice");
  r=Fresh();Modding.ModHooks.NewGame();Resources.All.Clear();Tick(r);Check(Local8Mod.Save.CoopSetupHintState==1&&Label("Local8 Co-op Setup Hint")==null,"unavailable native font consumed the notice");Time.unscaledTime+=2;Resources.All.Add(new TMP_FontAsset{name="Perpetua"});Tick(r);Check(Label("Local8 Co-op Setup Hint")?.enabled==true,"late native font could not show queued notice");
  foreach(string guard in new[]{"disabled","inactive","notgameplay","notready","dead","transition","paused","panel","charms","story","ending","card","shop","stag","dialogue","ui","canvas"}){
   r=Fresh(4);Modding.ModHooks.NewGame();Action undo;
   switch(guard){case "disabled":r.Enabled.Value=false;undo=()=>r.Enabled.Value=true;break;case "inactive":r.Session.Active=false;undo=()=>r.Session.Active=true;break;case "notgameplay":r.Session.Gameplay=false;undo=()=>r.Session.Gameplay=true;break;case "notready":r.Session.Primary.Ready=false;undo=()=>r.Session.Primary.Ready=true;break;case "dead":r.Session.Primary.Alive=false;undo=()=>r.Session.Primary.Alive=true;break;case "transition":GameManager.instance.IsLoadingSceneTransition=true;undo=()=>GameManager.instance.IsLoadingSceneTransition=false;break;case "paused":GameManager.instance.isPaused=true;undo=()=>GameManager.instance.isPaused=false;break;case "panel":r.Panel=true;undo=()=>r.Panel=false;break;case "charms":Charms.NativeMenuOpen=true;undo=()=>Charms.NativeMenuOpen=false;break;case "story":ScriptedParty.Active=true;undo=()=>ScriptedParty.Active=false;break;case "ending":CoopEnding.Active=true;undo=()=>CoopEnding.Active=false;break;case "card":PickupCard.Owner=r.Session.Primary;undo=()=>PickupCard.Owner=null;break;case "shop":ShopMenuRouting.Buyer=r.Session.Primary;undo=()=>ShopMenuRouting.Buyer=null;break;case "stag":StagMenuRouting.HasOwner=true;undo=()=>StagMenuRouting.HasOwner=false;break;case "dialogue":InteractionRouter.ActivePlayer=r.Session.Primary;undo=()=>InteractionRouter.ActivePlayer=null;break;case "ui":UIManager.instance.uiState=GlobalEnums.UIState.PAUSED;undo=()=>UIManager.instance.uiState=GlobalEnums.UIState.PLAYING;break;default:UIManager.instance.UICanvas.gameObject.activeInHierarchy=false;undo=()=>UIManager.instance.UICanvas.gameObject.activeInHierarchy=true;break;}
   Tick(r,25);Check(Local8Mod.Save.CoopSetupHintState==1&&Label("Local8 Co-op Setup Hint")==null,"blocked UI consumed notice: "+guard);undo();Tick(r);Check(Label("Local8 Co-op Setup Hint")?.enabled==true,"notice not resumed: "+guard);
  }
  r=Fresh(4);Modding.ModHooks.NewGame();RescueHint.Queue();Tick(r);Check(Label("Local8 Rescue Hint")==null,"rescue notice overlapped setup");for(int i=0;i<151;i++)Tick(r);Check(Label("Local8 Rescue Hint")?.enabled==true,"rescue notice lost instead of queued");
  var previous=Local8Mod.Save;Local8Mod.Save=new();Tick(r);Check(!CoopSetupHint.Pending&&Label("Local8 Co-op Setup Hint")==null,"another existing save inherited pending UI");Modding.ModHooks.NewGame();Tick(r);Check(CoopSetupHint.Pending&&Local8Mod.Save.CoopSetupHintState==2&&previous.CoopSetupHintState==2,"second new save did not get its own single notice");
  CoopSetupHint.Uninstall();Check(Modding.ModHooks.Subscribers==0&&!Label("Local8 Co-op Setup Hint"),"mod teardown leaked hook or label");
  Console.WriteLine("PASS "+checks+" new-save-only setup hint checks: persistence, existing saves, duplicate native events, solo/co-op, pause/modal/late UI, priority, configured key and all ten real translations. Unity UI IO is controlled.");
 }
}
